import {navigatePOForm} from './form-navigation.js';
import {statuses,actionLabels,paymentLabels,money,date,poDate,monthLabel,todayBangkok,validateItems,validatePODate,totals,summarizeMonth,vatBase} from './domain.js';
import {createPreviewAdapter} from './preview-adapter.js';
import {createPreviewDownload} from './preview-export.js';
const app=document.querySelector('#app'),modal=document.querySelector('#modal'),preview=createPreviewAdapter(),service=preview,configured=false;
const recoveryCallback=false;
let actor={id:'preview-office',role:'office',display_name:'พนักงานทดลอง',can_export_report:false},route='list',draft=null,detail=null,pending=false,loadSequence=0,toastTimer,activeReport=null,editingUser=null,userRecords=[],remoteNotifications=[],partialDecisionMode=false,previewExportURL='';
preview.setActor(actor);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const blank=()=>({department:'',name:'',spec:'',source:'',note:'',qty:'1',unit:'',unit_price:'',vat:false,payment_method:''});
const defaultDepartments=['อาหาร','ของหวาน','ผลไม้','ติ่มซำ','แซนวิช','สลัด','ครัวกลาง','แม่บ้าน','ออฟฟิศ','ช่าง','ภูดอย','บ้านโจ้','ท่ารั้ว'];
let currentDepartments=defaultDepartments;
const departments=()=>service.departments?service.departments():Promise.resolve(defaultDepartments);
const field=(id,label,value='',type='text',attrs='')=>{const required=label.endsWith(' *'),text=required?label.slice(0,-2):label;return `<div class="field"><label for="${id}">${text}${required?' <span class="required-mark">*</span>':''}</label><input id="${id}" type="${type}" value="${esc(value)}" ${attrs}><span id="${id}-error" class="field-error"></span></div>`;};
const badge=s=>`<span class="badge ${s}">${statuses[s]}</span>`;
function timeOnly(s){return new Intl.DateTimeFormat('th-TH',{timeStyle:'short',timeZone:'Asia/Bangkok'}).format(new Date(s));}
function shortPoDate(s){return new Intl.DateTimeFormat('th-TH',{day:'numeric',month:'short',year:'numeric',timeZone:'Asia/Bangkok'}).format(new Date(`${s}T12:00:00+07:00`));}
function tracker(p,large=false){const done={pending:0,approved:1,received:2,closed:3,rejected:0}[p.status];return `<ol class="tracker status-${p.status} ${large?'large':''}" aria-label="ขั้นตอนใบ PO">${['เปิด PO','อนุมัติ','รับสินค้า','ปิด PO'].map((s,n)=>`<li class="${n<=done?'done':n===done+1&&p.status!=='rejected'?'current':''}" ${n===done+1&&p.status!=='rejected'?'aria-current="step"':''}>${s}${n<=done?'<span class="sr-only"> เสร็จแล้ว</span>':''}</li>`).join('')}</ol>`;}
function notify(text){clearTimeout(toastTimer);document.querySelector('#toast').textContent=text;toastTimer=setTimeout(()=>document.querySelector('#toast').textContent='',5000);}
const notificationKey='po-the-grands-preview-notifications-v2';
function allNotifications(){try{return JSON.parse(localStorage.getItem(notificationKey)||'[]')}catch{return []}}
function myNotifications(){return configured?remoteNotifications:allNotifications().filter(n=>actor&&(actor.role==='owner'?n.recipient_role==='owner':n.recipient_id===actor.id));}
function addWorkflowNotification(po,action,sourceActor){const copy={create:['มีใบขอซื้อใหม่',`${sourceActor.display_name} เปิด ${po.po_number}`],approve:['ใบขอซื้อได้รับอนุมัติ',`${po.po_number} ได้รับอนุมัติแล้ว`],reject:['ใบขอซื้อไม่อนุมัติ',`${po.po_number} ไม่ได้รับอนุมัติ`],receive:['ได้รับสินค้าแล้ว',`${sourceActor.display_name} ยืนยันรับสินค้า ${po.po_number}`],close:['ปิดใบ PO แล้ว',`${po.po_number} ตรวจรับเอกสารและปิดแล้ว`]}[action];if(!copy)return;const rows=allNotifications(),event_key=`${po.id}:${action}:${po.version||1}`;if(rows.some(n=>n.event_key===event_key))return;rows.unshift({id:crypto.randomUUID(),event_key,po_id:po.id,recipient_role:['create','receive'].includes(action)?'owner':'office',recipient_id:['create','receive'].includes(action)?null:po.created_by,title:copy[0],message:copy[1],action,created_at:new Date().toISOString(),read_at:null});localStorage.setItem(notificationKey,JSON.stringify(rows.slice(0,100)));}
function notificationButton(){const unread=myNotifications().filter(n=>!n.read_at).length;return `<button type="button" class="notification-button" data-action="notifications" aria-label="การแจ้งเตือน${unread?`ที่ยังไม่ได้อ่าน ${unread} รายการ`:''}"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4"/></svg>${unread?`<span>${unread}</span>`:''}</button>`;}
async function refreshNotifications(){if(!configured||!actor)return;try{remoteNotifications=await service.notifications();const old=document.querySelector('.notification-button');if(old)old.outerHTML=notificationButton();}catch{}}
async function openNotifications(){const rows=myNotifications();openModal('การแจ้งเตือน',`<div class="notification-list">${rows.map(n=>`<button type="button" class="notification-item ${n.read_at?'':'unread'}" data-notification-po="${n.po_id}"><strong>${esc(n.title)}</strong><span>${esc(n.message)}</span><small>${date(n.created_at)}</small></button>`).join('')||'<div class="empty"><p>ยังไม่มีการแจ้งเตือน</p></div>'}</div><div class="actions"><button type="button" data-cancel>ปิด</button></div>`);if(configured){await service.markNotificationsRead();remoteNotifications=rows.map(n=>({...n,read_at:n.read_at||new Date().toISOString()}));}else{const all=allNotifications(),ids=new Set(rows.map(n=>n.id)),now=new Date().toISOString();for(const n of all)if(ids.has(n.id)&&!n.read_at)n.read_at=now;localStorage.setItem(notificationKey,JSON.stringify(all));}document.querySelector('.notification-button span')?.remove();}
function navButton(go,label){return `<button data-go="${go}" class="${route===go?'selected':''}">${label}</button>`;}
function shell(body){window.scrollTo(0,0);app.innerHTML=`<div class="shell route-${route}"><aside class="sidebar"><div><div class="logo"><img src="favicon.svg?v=20260927-3" alt=""><span class="brand-name">PO The <span class="brand-last">Grands</span></span></div><div class="side-caption">PURCHASE ORDER WORKSPACE</div></div><nav class="nav" aria-label="เมนูหลัก">${navButton('list','▤ &nbsp; ใบขอซื้อทั้งหมด')}${actor.role==='office'?navButton('create','＋ &nbsp; เปิดใบ PO'):''}${actor.role==='office'?navButton('departments','▥ &nbsp; แผนก/สาขา'):''}${actor.role==='office'?navButton('report','▦ &nbsp; สรุปรายเดือน'):''}${actor.role==='owner'?navButton('users','♙ &nbsp; ผู้ใช้งาน'):''}${configured&&actor.role==='owner'?navButton('account','⚙ &nbsp; บัญชีของฉัน'):''}</nav></aside><main class="main"><header class="topbar"><span>พื้นที่ทำงาน / ใบขอซื้อ</span><div class="identity"><span class="avatar" aria-hidden="true">${actor.role==='owner'?'♛':'♙'}</span><strong>${esc(actor.display_name)}</strong><button data-action="logout" class="ghost"><span class="account-switch-label">เปลี่ยนบัญชี<span class="account-switch-last">ผู้ใช้งาน</span></span></button></div></header><div class="content">${!configured?'<div class="demo-banner"><span><strong>ระบบทดลอง</strong> · ข้อมูล PO จะเริ่มใหม่เมื่อรีโหลดหน้า ส่วนบัญชีทดลองเก็บเฉพาะเครื่องนี้</span><button data-go="setup">ดูการเชื่อมต่อ</button></div>':''}${body}</div></main></div>`;document.title=({list:'ใบขอซื้อ',create:'เปิดใบ PO',review:'ตรวจทานใบ PO',detail:detail?.po_number||'รายละเอียด',report:'สรุปรายเดือน',users:'ผู้ใช้งาน',account:'บัญชีของฉัน',setup:'การเชื่อมต่อ'}[route]||'เข้าสู่ระบบ')+' — PO The Grands';}
function showError(e,target=document.querySelector('#page-error')){if(target){target.innerHTML=`<div class="error" role="alert">${esc(e.message||e)}${e.authExpired?' <button data-action="reauth">เข้าสู่ระบบอีกครั้ง</button>':''}</div>`;target.scrollIntoView({block:'nearest'});}else notify(e.message||String(e));}
function openModal(title,body,onSubmit){const prev=document.activeElement;modal.innerHTML=`<h2 id="modal-title">${title}</h2>${body}`;modal.showModal();modal.querySelector('[data-cancel]')?.addEventListener('click',()=>modal.close());modal.onclose=()=>{if(prev?.isConnected)prev.focus();};modal.oncancel=e=>{if(pending)e.preventDefault();};const form=modal.querySelector('form');if(form)form.onsubmit=async e=>{e.preventDefault();if(!pending)await onSubmit(new FormData(form));};}
function errorField(input,message){input.setAttribute('aria-invalid','true');input.setAttribute('aria-describedby',input.id+'-error');document.getElementById(input.id+'-error').textContent=message;input.focus();}
async function withPending(button,task,errorTarget){if(pending)return;pending=true;const buttons=[...document.querySelectorAll('button')],states=buttons.map(b=>b.disabled);buttons.forEach(b=>b.disabled=true);button?.setAttribute('aria-busy','true');try{await task();}catch(e){showError(e,errorTarget||document.querySelector('#page-error'));}finally{pending=false;buttons.forEach((b,i)=>{if(b.isConnected)b.disabled=states[i];});button?.removeAttribute('aria-busy');}}
function passwordControl(id,label,autocomplete='current-password',value=''){return `<div class="field"><label for="${id}">${label}</label><div class="password-wrap"><input id="${id}" name="${id}" type="password" autocomplete="${autocomplete}" value="${esc(value)}"><button type="button" class="password-toggle" data-reveal="${id}" aria-label="แสดง${label}" aria-pressed="false"><svg class="eye-icon eye-open" viewBox="0 0 24 24" aria-hidden="true"><path d="M2 12s3.5-6 10-6 10 6 10 6-3.5 6-10 6S2 12 2 12Z"/><circle cx="12" cy="12" r="2.8"/></svg><svg class="eye-icon eye-closed" viewBox="0 0 24 24" aria-hidden="true"><path d="m3 3 18 18M10.6 5.9A10.8 10.8 0 0 1 12 5.8c6.5 0 10 6.2 10 6.2a19 19 0 0 1-3.4 3.9M6.3 6.3C3.5 8.1 2 12 2 12s3.5 6 10 6c1.4 0 2.7-.3 3.8-.7"/><path d="M9.9 9.9a3 3 0 0 0 4.2 4.2"/></svg></button></div><span class="field-error" id="${id}-error"></span></div>`;}
function bindPasswordToggles(){document.querySelectorAll('[data-reveal]').forEach(button=>button.onclick=()=>{const input=document.getElementById(button.dataset.reveal),show=input.type==='password';input.type=show?'text':'password';button.setAttribute('aria-label',(show?'ซ่อน':'แสดง')+'รหัสผ่าน');button.setAttribute('aria-pressed',String(show));button.classList.toggle('is-visible',show);});}
function login(){notify('ระบบทดลองใช้ปุ่มเปลี่ยนบัญชีผู้ใช้งานเพื่อเลือกบทบาทจำลอง');}
function resetOwner(){login();}
function requestOwnerRecovery(){login();}
function invalidOwnerRecovery(){login();}
function beginOwnerRecovery(){login();}
function getFilter(){const s=new URLSearchParams(location.search).get('status')||'';return s in statuses?s:'';}
function getPage(){return Math.max(1,Math.floor(Number(new URLSearchParams(location.search).get('page'))||1));}
function getScope(){if(actor?.role!=='office')return'all';if(!actor.can_export_report)return'mine';return new URLSearchParams(location.search).get('scope')==='mine'?'mine':'all';}
function setListState(status,page,scope=getScope()){const params=new URLSearchParams();if(status)params.set('status',status);if(page>1)params.set('page',page);if(actor?.role==='office'&&actor.can_export_report&&scope==='mine')params.set('scope','mine');history.pushState({},'',location.pathname+(params.size?'?'+params:''));return renderList({preserveShell:true});}
function listFrameMarkup(status,scope){
 const scopeFilter=actor.role==='office'&&actor.can_export_report?`<div class="scope-filter" aria-label="กรองตามผู้เปิดใบ PO"><button data-scope="all" class="${scope==='all'?'selected':''}" aria-pressed="${scope==='all'}">ทุกคน</button><button data-scope="mine" class="${scope==='mine'?'selected':''}" aria-pressed="${scope==='mine'}">ของฉัน</button></div>`:'';
 const filterButtons=`<div class="filters" aria-label="กรองสถานะ">${[['','ทั้งหมด'],...Object.entries(statuses)].map(([s,label])=>`<button data-filter="${s}" class="${status===s?'selected':''}" aria-pressed="${status===s}">${label}</button>`).join('')}</div>`;
 return `<div id="po-metrics" class="metrics" hidden></div><section class="panel"><div id="po-panel-head" class="panel-head" hidden><h2>รายการใบ PO</h2><button data-action="refresh" class="ghost">↻ โหลดล่าสุด</button></div>${scopeFilter}${filterButtons}<div id="po-orders" class="orders" style="margin-top:20px"></div><div id="po-pagination" class="pagination" hidden></div></section>`;
}
function fillListFrame(target,list,stats,status,scope){
 const metrics=document.querySelector('#po-metrics');
 const metricStatuses=['pending','approved','received','closed','rejected'];
 metrics.hidden=false;
 metrics.className='metrics';
 metrics.innerHTML=metricStatuses.map(s=>`<div class="metric"><span class="marker"></span><small>${statuses[s]}</small><strong>${Number(stats[s]||0)} <small>ใบ</small></strong></div>`).join('');
 const panelHead=document.querySelector('#po-panel-head');
 panelHead.hidden=false;
 for(const button of target.querySelectorAll('[data-filter]')){const selected=button.dataset.filter===status;button.classList.toggle('selected',selected);button.setAttribute('aria-pressed',String(selected));}
 for(const button of target.querySelectorAll('[data-scope]')){const selected=button.dataset.scope===scope;button.classList.toggle('selected',selected);button.setAttribute('aria-pressed',String(selected));}
 const orders=document.querySelector('#po-orders');
 orders.innerHTML=list.rows.map(p=>`<article class="order"><div><span class="order-id">${esc(p.po_number)}</span><h3>${esc(p.items[0].name)}${p.items.length>1?` <small>และอีก ${p.items.length-1} รายการ</small>`:''}</h3><small>${esc(p.requester_name)} · ${poDate(p.po_date)}</small></div><div class="order-progress">${badge(p.status)}${tracker(p)}</div><div class="order-actions"><div class="amount">฿ ${money(p.total_cents)}</div><button data-detail="${p.id}">ดูรายละเอียด ↗</button></div></article>`).join('')||`<div class="empty"><h2>${status?'ยังไม่มีใบ PO ในสถานะนี้':'ยังไม่มีใบ PO'}</h2><p>${actor.role==='office'?'เริ่มจากเปิดใบ PO และตรวจทานรายการก่อนส่งให้เจ้าของ':'เมื่อออฟฟิศเปิดใบ PO คำขอจะแสดงที่นี่'}</p>${actor.role==='office'?'<button data-go="create" class="primary">＋ เปิดใบ PO</button>':''}</div>`;
 const pagination=document.querySelector('#po-pagination');
 pagination.hidden=list.total===0;
 pagination.innerHTML=list.total?`<span>${(getPage()-1)*10+1}–${Math.min(getPage()*10,list.total)} จาก ${list.total} ใบ</span><div class="row"><button data-page="${getPage()-1}" ${getPage()===1?'disabled':''}>ก่อนหน้า</button><span>หน้า ${getPage()}</span><button data-page="${getPage()+1}" ${getPage()*10>=list.total?'disabled':''}>ถัดไป</button></div>`:'';
}
async function renderList({preserveShell=false}={}){
 route='list';
 const seq=++loadSequence,status=getFilter(),page=getPage(),scope=getScope();
 let target=preserveShell?document.querySelector('#list-content'):null;
 const reused=Boolean(target);
 if(!reused){
  shell(`<div class="page-head"><div><div class="eyebrow">PURCHASE ORDERS</div><h1>ใบขอซื้อ</h1><p class="muted">ติดตามคำขอ ตั้งแต่อนุมัติจนได้รับใบกำกับภาษี</p></div>${actor.role==='office'?'<button class="primary" data-go="create">＋ เปิดใบ PO</button>':''}</div><div id="page-error"></div><div id="list-content" class="loading" role="status">กำลังโหลดใบ PO…</div>`);
  target=document.querySelector('#list-content');
 }else target.setAttribute('aria-busy','true');
 try{
  const [list,stats]=await Promise.all([service.list(status,page,scope),service.stats(scope)]);
  if(seq!==loadSequence||route!=='list')return;
  if(!list.rows.length&&page>1)return setListState(status,Math.max(1,Math.ceil(list.total/10)),scope);
  if(!target.querySelector('#po-orders'))target.innerHTML=listFrameMarkup(status,scope);
  target.className='';target.removeAttribute('role');target.removeAttribute('aria-busy');
  fillListFrame(target,list,stats,status,scope);
  const errorRegion=document.querySelector('#page-error');if(errorRegion)errorRegion.innerHTML='';
 }catch(e){
  if(seq!==loadSequence)return;
  target.removeAttribute('aria-busy');
  if(!reused)target.innerHTML='<button data-action="refresh">ลองโหลดใหม่</button>';
  showError(e);
  if(reused)document.querySelector('#page-error')?.insertAdjacentHTML('beforeend','<button data-action="refresh">ลองโหลดใหม่</button>');
 }
}

function lineForm(i,n){return `<fieldset class="line-entry"><legend>รายการ ${n+1}</legend><div class="field"><label for="department-${n}">แผนก/สาขา <span class="required-mark">*</span></label><input id="department-${n}" list="department-options-${n}" value="${esc(i.department||'')}" placeholder="ค้นหาแผนก/สาขา" autocomplete="off" data-index="${n}" data-key="department" data-department-field><datalist id="department-options-${n}">${currentDepartments.map(d=>`<option value="${esc(d)}">`).join('')}</datalist><span id="department-${n}-error" class="field-error"></span></div><div class="row spread"><span class="form-note">รายละเอียดสินค้า</span>${draft.items.length>1?`<button type="button" class="ghost danger" data-remove="${n}">ลบรายการ ${n+1}</button>`:''}</div>${field('name-'+n,'ชื่อสินค้า *',i.name,'text',`data-index="${n}" data-key="name" maxlength="200"`)}<div class="field"><label for="spec-${n}">รายละเอียด / สเปคสินค้า <span class="required-mark">*</span></label><textarea id="spec-${n}" data-index="${n}" data-key="spec" maxlength="2000">${esc(i.spec)}</textarea><span id="spec-${n}-error" class="field-error"></span></div>${field('source-'+n,'แหล่งซื้อ *',i.source,'text',`data-index="${n}" data-key="source" maxlength="300" placeholder="ชื่อร้าน ผู้ขาย หรือเว็บไซต์"`)}<div class="line-grid quantity-grid">${field('qty-'+n,'จำนวน *',i.qty,'number',`data-index="${n}" data-key="qty" min="0.001" max="1000000" step="0.001" inputmode="decimal"`)}${field('unit-'+n,'หน่วย *',i.unit||'','text',`data-index="${n}" data-key="unit" `)}${field('unit_price-'+n,'ราคาต่อหน่วย (บาท) *',i.unit_price,'number',`data-index="${n}" data-key="unit_price" min="0.01" step="0.01" inputmode="decimal"`)}<div class="field"><span>ภาษี</span><label class="check"><input type="checkbox" data-index="${n}" data-key="vat" ${i.vat?'checked':''}> VAT 7% <span class="muted">(ไม่ติ๊ก = NON VAT)</span></label></div></div><fieldset class="payment-choice"><legend>การชำระเงิน <span class="required-mark">*</span></legend><div class="payment-options">${Object.entries(paymentLabels).map(([value,label])=>`<label class="payment-option" for="payment-${value}-${n}"><input id="payment-${value}-${n}" type="radio" name="payment-method-${n}" value="${value}" data-index="${n}" data-key="payment_method" aria-describedby="payment-credit-${n}-error" ${i.payment_method===value?'checked':''}> ${esc(label)}</label>`).join('')}</div><span id="payment-credit-${n}-error" class="field-error"></span></fieldset><div class="vat-calc" id="vat-calc-${n}"></div><div class="field"><label for="note-${n}">หมายเหตุ</label><textarea id="note-${n}" data-index="${n}" data-key="note" maxlength="2000" placeholder="รายละเอียดเพิ่มเติม (ถ้ามี)">${esc(i.note)}</textarea><span id="note-${n}-error" class="field-error"></span></div><div class="right muted" id="line-total-${n}"></div></fieldset>`;}
function updateTotals(){let total=0,base=0,tax=0;draft.items.forEach((i,n)=>{try{const line=validateItems([{...i,name:i.name||'สินค้า',spec:i.spec||'รายละเอียด',source:i.source||'แหล่งซื้อ'}])[0];total+=line.total_cents;base+=line.vat?line.base_cents:0;tax+=line.tax_cents;document.querySelector('#line-total-'+n).textContent='รวมรายการนี้ ฿ '+money(line.total_cents);document.querySelector('#vat-calc-'+n).innerHTML=i.vat?`<span>คำนวณอัตโนมัติจากราคารวม VAT</span><strong>ก่อน VAT ฿ ${money(line.base_cents)} · VAT ฿ ${money(line.tax_cents)}</strong>`:'<span>NON VAT</span>';}catch{document.querySelector('#line-total-'+n).textContent='';document.querySelector('#vat-calc-'+n).textContent='';}});document.querySelector('#draft-base').textContent='฿ '+money(base);document.querySelector('#draft-tax').textContent='฿ '+money(tax);document.querySelector('#draft-total').textContent='฿ '+money(total);}
async function renderCreate(){route='create';++loadSequence;if(!draft)draft={po_date:todayBangkok(),department:'',items:[blank()],key:crypto.randomUUID(),dirty:false};let deptList;try{deptList=await departments();}catch(e){shell('<div id="page-error"></div><button data-go="create">ลองโหลดแผนก/สาขาอีกครั้ง</button>');showError(e);return;}if(route!=='create')return;currentDepartments=deptList;shell(`<div class="page-head"><div><div class="eyebrow">${draft.revision?'EDIT PURCHASE ORDER ITEM':'NEW PURCHASE ORDER'}</div><h1>${draft.revision?'แก้ไขรายการสินค้า':'เปิดใบ PO'}</h1><p class="muted">${draft.revision?'ปรับข้อมูลรายการเดิมแล้วส่งให้เจ้าของพิจารณาใหม่':'กรอกรายการ แล้วตรวจทานก่อนส่งอนุมัติ'}</p></div>${draft.revision?`<button data-detail="${draft.revision.poId}">กลับรายละเอียด</button>`:'<button data-go="list">กลับรายการ</button>'}</div><section class="panel"><h2>${draft.revision?'รายละเอียดรายการที่แก้ไข':'รายละเอียดใบขอซื้อ'}</h2><form id="po-form" novalidate><div id="page-error"></div><div class="date-row">${field('po-date','วันที่ใบ PO *',draft.po_date,'date',`${draft.revision?'disabled':''} data-header-key="po_date"`)}<div class="field"><span>เวลาบันทึก</span><div class="read-only-value">บันทึกอัตโนมัติเมื่อเปิด PO</div></div></div>${draft.items.map(lineForm).join('')}${draft.revision?'':`<button type="button" data-action="add" ${draft.items.length>=50?'disabled':''}>＋ เพิ่มสินค้า</button>`}<div class="summary"><div class="row spread"><span>รวมก่อน VAT</span><strong id="draft-base">฿ 0.00</strong></div><div class="row spread"><span>VAT รวม</span><strong id="draft-tax">฿ 0.00</strong></div><hr><div class="row spread"><strong>ยอดรวมสุทธิ</strong><strong class="grand" id="draft-total">฿ 0.00</strong></div></div><div class="actions"><button type="button" data-go="list">ยกเลิก</button><button type="submit" class="primary">${draft.revision?'ตรวจทานและส่งอนุมัติใหม่':'ตรวจทานใบ PO →'}</button></div></form></section>`);updateTotals();document.querySelector('#po-form').onsubmit=e=>{e.preventDefault();const invalidDepartment=draft.items.findIndex(i=>!deptList.includes(String(i.department||'').trim()));if(invalidDepartment>=0){errorField(document.querySelector('#department-'+invalidDepartment),'เลือกแผนก/สาขาที่มีในระบบ');return;}const invalidPayment=draft.items.findIndex(i=>!Object.hasOwn(paymentLabels,i.payment_method));if(invalidPayment>=0){const input=document.querySelector('#payment-credit-'+invalidPayment);document.querySelectorAll(`[name="payment-method-${invalidPayment}"]`).forEach(radio=>radio.setAttribute('aria-invalid','true'));errorField(input,'เลือกการชำระเงิน เครดิต หรือเงินสด');return;}draft.department=[...new Set(draft.items.map(i=>i.department.trim()))].length===1?draft.items[0].department.trim():'หลายแผนก/สาขา';try{draft.po_date=validatePODate(draft.po_date);draft.validated=validateItems(draft.items);renderReview();}catch(err){showError(err);if(!/^20/.test(draft.po_date)){errorField(document.querySelector('#po-date'),err.message);return;}const n=err.index||0,item= draft.items[n];let key=!item.name.trim()?'name':!item.spec.trim()?'spec':!item.source.trim()?'source':!(Number(item.qty)>0)?'qty':'unit_price';errorField(document.getElementById(key+'-'+n),err.message);}};}
function itemsTable(items){return `<div class="table-wrap" tabindex="0" role="region" aria-label="รายการสินค้า เลื่อนแนวนอนเพื่อดูทั้งหมด"><table><thead><tr><th>สินค้า / สเปค</th><th>แผนก/สาขา</th><th>แหล่งซื้อ</th><th>การชำระเงิน</th><th class="right">จำนวน</th><th class="right">ราคา / หน่วย</th><th>ภาษี</th><th class="right">รวม (บาท)</th></tr></thead><tbody>${items.map(i=>`<tr><td><strong>${esc(i.name)}</strong><small>${esc(i.spec)}</small>${i.note?`<small>หมายเหตุ: ${esc(i.note)}</small>`:''}</td><td>${esc(i.department||'-')}</td><td>${esc(i.source)}</td><td>${esc(paymentLabels[i.payment_method]||'ไม่ระบุ')}</td><td class="right">${esc(i.qty)} ${esc(i.unit||'ชิ้น')}</td><td class="right">${money(Math.round(Number(i.unit_price)*100))}</td><td>${i.vat?`VAT 7%<small>ก่อน VAT ${money(i.base_cents)}<br>VAT ${money(i.tax_cents)}</small>`:'NON VAT'}</td><td class="right number">${money(i.total_cents)}</td></tr>`).join('')}</tbody></table></div>`;}
function summary(t,items=[]){return `<div class="summary"><div class="row spread"><span>รวมก่อน VAT <small>(เฉพาะรายการ VAT)</small></span><strong>฿ ${money(vatBase(items))}</strong></div><div class="row spread"><span>VAT รวม</span><strong>฿ ${money(t.tax_cents)}</strong></div><hr><div class="row spread"><strong>ยอดรวมสุทธิ</strong><strong class="grand">฿ ${money(t.total_cents)}</strong></div></div>`;}
function renderReview(){route='review';shell(`<div class="page-head"><div><div class="eyebrow">REVIEW & SUBMIT</div><h1>${draft.revision?'ตรวจทานรายการก่อนส่งอนุมัติใหม่':'ตรวจทานก่อนเปิด PO'}</h1><p class="muted">ตรวจชื่อสินค้า แหล่งซื้อ จำนวน และราคาให้ครบ</p></div></div><section class="panel"><div class="row spread"><h2>สรุปคำขอซื้อ</h2><strong>${poDate(draft.po_date)}</strong></div><p class="form-note"><strong>แผนก/สาขา:</strong> ${esc(draft.department)}</p>${itemsTable(draft.validated)}${summary(totals(draft.validated),draft.validated)}<p class="form-note">${draft.revision?'รายการเดิมจะยังไม่มียอดสั่งซื้อจนกว่าเจ้าของจะอนุมัติข้อมูลที่แก้ไข':'เมื่อเปิด PO แล้ว รายการนี้จะส่งให้เจ้าของพิจารณา และไม่สามารถแก้ไขสินค้า / ราคาในใบเดิมได้'}</p><div id="page-error"></div><div class="actions"><button data-action="edit">← กลับไปแก้ไข</button><button data-action="submit" class="primary">${draft.revision?'ส่งอนุมัติรายการที่แก้ไข':'ยืนยันเปิด PO'}</button></div></section>`);}
async function renderDetail(id){if(detail?.id!==id)partialDecisionMode=false;route='detail';const seq=++loadSequence;shell('<div id="page-error"></div><div id="detail-content" class="loading">กำลังโหลดรายละเอียด…</div>');try{const p=await service.detail(id);if(seq!==loadSequence||route!=='detail')return;detail=p;const creator=actor.role==='office'&&p.created_by===actor.id,owner=actor.role==='owner',primary=actor.role==='office'&&actor.can_export_report===true,live=p.items.filter(i=>!['received','rejected'].includes(i.state)),pendingItems=p.items.filter(i=>i.state==='pending'),approvedItems=p.items.filter(i=>i.state==='approved'),wholeApprove=owner&&service.workflow.bulkApproveReady(p),wholeReceive=(creator||primary)&&service.workflow.bulkReceiveReady(p),wholeReject=owner&&p.items.length>0&&p.items.every(i=>i.state==='pending');let actions='';if(owner&&!p.closed_at){actions+=`<button class="primary" data-command="approve" ${wholeApprove?'':'disabled title="ยังมีรายการที่ต้องแก้ไข หรือไม่มีรายการรออนุมัติ"'}>อนุมัติทั้งใบ PO</button>`;if(!wholeApprove&&live.some(i=>i.state==='pending'))actions+=`<p class="form-note">มีรายการที่ต้องแก้ไขหรือพิจารณาแยก จึงยังอนุมัติทั้งใบไม่ได้</p>`;if(wholeReject)actions+=`<button class="danger" data-command="reject_all">ไม่อนุมัติทั้งใบ PO</button>`;else if(pendingItems.length)actions+=`<button class="danger" data-command="reject_all" disabled title="ไม่อนุมัติทั้งใบได้เมื่อทุกรายการยังรออนุมัติ">ไม่อนุมัติทั้งใบ PO</button>`;actions+=`<button data-command="partial_mode">${partialDecisionMode?'ปิดโหมดอนุมัติบางรายการ':'อนุมัติบางรายการ'}</button>`;}if((creator||primary)&&!p.closed_at&&live.length){actions+=`<button class="primary" data-command="receive" ${wholeReceive?'':'disabled title="รับทั้งใบได้เมื่อทุกรายการที่เหลือได้รับอนุมัติแล้ว"'}>ยืนยันรับสินค้าทั้งใบ PO</button>`;if(approvedItems.length&&!wholeReceive)actions+=`<button data-command="partial_mode">${partialDecisionMode?'เปิดการรับแยกรายการ':'รับแยกรายการ'}</button>`;}if(owner&&p.status==='received'&&!p.closed_at)actions+=`<button class="primary" data-command="close">ตรวจรับใบกำกับภาษีและปิด PO</button>`;const itemActions=p.items.map(item=>{const name=esc(item.name),button=(action,label,kind='')=>`<button type="button" class="${kind}" data-command="${action}" data-item-id="${esc(item.id)}" aria-label="${label} · ${name}">${label}</button>`;if(p.closed_at||item.state==='received'||item.state==='rejected')return'';if(actor.role==='owner'&&item.state==='revision_requested')return `<div class="row"><button data-command="unlock_item" data-item-id="${esc(item.id)}">ปลดล็อกแก้ไข · ${name}</button><button data-command="refuse_revision" data-item-id="${esc(item.id)}">ปฏิเสธคำขอ · ${name}</button></div>`;if(creator&&['returned','editing'].includes(item.state))return `<button data-command="edit_item" data-item-id="${esc(item.id)}">แก้ไขรายการ · ${name}</button>`;if(creator&&['approved','pending'].includes(item.state))return button('request_revision','ขอแก้ไข · '+name,'');if(partialDecisionMode&&owner&&item.state==='pending')return `<div class="row">${button('approve_item','อนุมัติรายการ · '+name,'primary')}${button('return_item','ส่งกลับแก้ไข · '+name)}${button('reject_item','ไม่อนุมัติรายการ · '+name,'danger')}</div>`;if(partialDecisionMode&&(creator||primary)&&item.state==='approved')return button('receive_item','ยืนยันรับสินค้า · '+name,'primary');return'';}).filter(Boolean).join('');const chosenItems=p.items.filter(i=>['approved','received'].includes(i.state));const resolvedSummary=summary(totals(chosenItems),chosenItems);const statusContext=p.items.some(i=>['pending','returned','revision_requested','editing'].includes(i.state))&&p.items.some(i=>['approved','received'].includes(i.state))?'<div class="form-note">ใบ PO มีทั้งรายการที่ดำเนินการแล้วและรายการที่ยังรอการตัดสินใจ รายการที่พักไว้จะไม่รวมในยอดสั่งซื้อ</div>':'';shell(`<div class="page-head"><div><div class="eyebrow">PURCHASE ORDER</div><h1>${esc(p.po_number)}</h1><p class="muted po-meta"><span class="po-meta-date">วันที่ PO ${shortPoDate(p.po_date)} · ${timeOnly(p.created_at)} น.</span><span class="po-meta-requester">เปิดโดย ${esc(p.requester_name)}</span></p></div><button type="button" data-go="list" class="po-back" aria-label="กลับไปหน้ารายการ PO" title="กลับไปหน้ารายการ PO"><span aria-hidden="true">←</span></button></div><div id="page-error"></div><section class="panel"><div class="row spread"><h2>สถานะใบ PO</h2>${badge(p.status)}</div>${tracker(p,true)}${p.status==='rejected'?`<div class="error"><strong>เหตุผลที่ไม่อนุมัติ</strong><br>${esc(p.items.find(i=>i.state==='rejected')?.reject_reason||'')}</div>`:''}${p.status==='received'?'<div class="summary">ได้รับสินค้าครบแล้ว · รอออฟฟิศนำใบกำกับภาษีให้เจ้าของ เจ้าของต้องตรวจรับเอกสารก่อนปิด PO</div>':''}${p.status==='closed'?'<div class="summary">✓ เจ้าของยืนยันได้รับใบกำกับภาษีและปิด PO แล้ว</div>':''}${statusContext}${actions?`<div class="actions">${actions}</div>`:''}${itemActions?`<div class="preview-item-controls"><h3>${partialDecisionMode?'การดำเนินการแยกรายการ':'คำขอแก้ไขของรายการ'}</h3>${itemActions}</div>`:''}</section><section class="panel"><h2>รายการสินค้า <small>${p.items.length} รายการ</small></h2>${itemsTable(p.items)}${resolvedSummary}</section><section class="panel"><h2>ประวัติการดำเนินการ</h2><ol class="audit">${(p.events||[]).map(e=>`<li><strong>${actionLabels[e.action]||({approve_all:'อนุมัติทั้งใบ PO',approve:'อนุมัติรายการ',return:'ส่งกลับแก้ไข',request_revision:'ขอแก้ไขรายการ',unlock:'ปลดล็อกแก้ไข',refuse_revision:'ปฏิเสธคำขอแก้ไข',resubmit:'ส่งอนุมัติใหม่',receive:'รับสินค้า',close:'ตรวจรับใบกำกับภาษีและปิด PO'}[e.action])||esc(e.action)}</strong>${e.item_name?` · ${esc(e.item_name)}`:''} · ${esc(e.actor_name)}<small>${date(e.at)} (เวลาไทย)</small>${e.reason?`<p>${esc(e.reason)}</p>`:''}${e.before&&e.after?`<details><summary>ดูข้อมูลก่อนและหลังแก้ไข · ผลต่าง ฿ ${money(e.delta_cents)}</summary><div><h4>ก่อนแก้ไข</h4>${itemsTable([e.before])}<h4>หลังแก้ไข</h4>${itemsTable([e.after])}</div></details>`:''}</li>`).join('')}</ol></section>`);}catch(e){showError(e);const target=document.querySelector('#detail-content');if(target)target.innerHTML='<button type="button" data-go="list" class="po-back" aria-label="กลับไปหน้ารายการ PO" title="กลับไปหน้ารายการ PO">←</button>';}}

function command(action,itemId=null){if(action==='partial_mode'){partialDecisionMode=!partialDecisionMode;return renderDetail(detail.id);}if(action==='edit_item'){const item=detail.items.find(i=>i.id===itemId);if(!item)return;draft={po_date:detail.po_date,department:item.department||'',items:[{...item}],key:crypto.randomUUID(),dirty:false,revision:{poId:detail.id,itemId:item.id,version:detail.version}};return renderCreate();}const p=detail,key=crypto.randomUUID(),labels={approve:'อนุมัติทั้งใบ PO',reject_all:'ไม่อนุมัติทั้งใบ PO',approve_item:'อนุมัติรายการ',return_item:'ส่งกลับแก้ไขรายการ',reject_item:'ไม่อนุมัติรายการ',request_revision:'ขอแก้ไขรายการ',unlock_item:'ปลดล็อกแก้ไขรายการ',refuse_revision:'ปฏิเสธคำขอแก้ไข',receive:'ยืนยันรับสินค้าทั้งใบ PO',receive_item:'ยืนยันรับสินค้า',close:'ตรวจรับใบกำกับภาษีและปิด PO'},title=labels[action]||action,item=p.items.find(i=>i.id===itemId),requiresReason=['reject_all','reject_item','return_item','request_revision','unlock_item','refuse_revision'].includes(action);openModal(title,`<p><strong>${esc(p.po_number)}</strong>${item?` · ${esc(item.name)}`:''}</p><form novalidate><div id="modal-error"></div>${requiresReason?`<div class="field"><label for="reason">${action==='request_revision'?'เหตุผลที่ขอแก้ไข':action==='unlock_item'?'เหตุผลที่ปลดล็อก':'เหตุผล'} *</label><textarea id="reason" name="reason" maxlength="2000"></textarea><span class="field-error" id="reason-error"></span></div>`:action==='approve'||action==='approve_item'?'<div class="field"><label for="reason">หมายเหตุการอนุมัติ (ถ้ามี)</label><textarea id="reason" name="reason" maxlength="2000"></textarea></div>':`<label class="check"><input type="checkbox" id="ack" name="ack">${action==='close'?'ฉันได้รับใบกำกับภาษีจากออฟฟิศและตรวจสอบแล้ว':action==='receive_item'?'ฉันได้รับสินค้ารายการนี้ครบแล้ว':'ฉันได้รับสินค้าครบทุกรายการที่อนุมัติแล้ว'}</label><span id="ack-error" class="field-error"></span>`}${action==='close'?'<p class="form-note">ปิดได้เมื่อทุกรายการได้รับแล้วหรือไม่อนุมัติ และมีอย่างน้อยหนึ่งรายการรับแล้ว</p>':''}<div class="actions"><button type="button" data-cancel autofocus>กลับ</button><button type="submit" class="${['reject_all','reject_item','return_item'].includes(action)?'danger':'primary'}">ยืนยัน${title}</button></div></form>`,async data=>{const reason=String(data.get('reason')||'').trim(),confirmed=data.get('ack')==='on';if(requiresReason&&!reason){errorField(document.querySelector('#reason'),'กรุณาระบุเหตุผล');return;}if(['receive','receive_item','close'].includes(action)&&!confirmed){errorField(document.querySelector('#ack'),'กรุณาติ๊กยืนยันก่อนบันทึก');return;}await withPending(modal.querySelector('[type=submit]'),async()=>{const commandAction=action==='reject_item'?'reject_item':action;await service.action(p,commandAction,reason,confirmed,key,actor,itemId);modal.close();partialDecisionMode=false;await renderDetail(p.id);notify('บันทึกสำเร็จ: '+title);},document.querySelector('#modal-error'));});}

async function renderReport(month=todayBangkok().slice(0,7)){route='report';const seq=++loadSequence;shell(`<div class="page-head"><div><div class="eyebrow">MONTHLY SUMMARY</div><h1>สรุปรายเดือน</h1><p class="muted">ยอดสั่งซื้อคิดจากใบที่เจ้าของอนุมัติแล้ว</p></div></div><section class="panel"><div class="report-controls">${field('report-month','เลือกเดือน',month,'month')}<button class="report-export" data-action="export" disabled>⇩ Export Excel</button></div><div id="page-error"></div><div id="report-content" class="loading">กำลังคำนวณสรุป…</div></section>`);document.querySelector('#report-month').addEventListener('change',e=>renderReport(e.currentTarget.value||todayBangkok().slice(0,7)));try{const report=await service.report(month);if(seq!==loadSequence||route!=='report')return;activeReport={...report,month};renderReportContent(activeReport);}catch(e){showError(e);document.querySelector('#report-content').innerHTML='<button data-action="retry-report">ลองโหลดใหม่</button>';}}
