document.addEventListener('click',e=>{const button=e.target.closest('[data-user-edit]');if(!button)return;queueMicrotask(()=>{const user=userRecords[Number(button.dataset.userEdit)],permission=document.querySelector('#can-export-report');if(permission&&user)permission.checked=user.can_export_report===true;});});
document.addEventListener('input',e=>{const input=e.target;if(!input.matches?.('input,textarea,select')||input.getAttribute('aria-invalid')!=='true')return;input.removeAttribute('aria-invalid');input.removeAttribute('aria-describedby');const error=document.getElementById(input.id+'-error');if(error)error.textContent='';});
document.addEventListener('submit',e=>{if(e.target.id!=='po-form')return;const department=[...document.querySelectorAll('[data-department-field]')].find(input=>!input.value.trim()),missingUnit=[...document.querySelectorAll('[data-key="unit"]')].find(input=>!input.value.trim()),invalid=department&&!department.value.trim()?department:missingUnit;if(!invalid)return;e.preventDefault();e.stopImmediatePropagation();errorField(invalid,invalid===department?'เลือกแผนก/สาขา':'กรอกหน่วย เช่น กล่อง แพ็ก ชิ้น หรือกิโลกรัม');},true);



document.addEventListener('keydown',navigatePOForm);

function selectPreviewRole(role){discardDraftThen(()=>{actor=previewActor(role);preview.setActor(actor);partialDecisionMode=false;history.replaceState({},'',location.pathname);modal.close();renderList();});}
document.addEventListener('click',event=>{const role=event.target.closest('[data-preview-role]');if(role){selectPreviewRole(role.dataset.previewRole);return;}const reset=event.target.closest('[data-preview-reset]');if(reset){openModal('คืนชุดข้อมูลทดลอง?',`<p>รายการสังเคราะห์ในชุดทดลองใหม่นี้จะถูกคืนค่า ข้อมูลทดลองรุ่นก่อนหน้าแยกไว้และจะไม่นำเข้ามา</p><div class="actions"><button type="button" data-cancel autofocus>กลับ</button><button type="button" class="danger" id="preview-reset-confirm">คืนชุดตัวอย่าง</button></div>`);document.querySelector('#preview-reset-confirm').onclick=()=>{draft=null;partialDecisionMode=false;preview.reset();modal.close();history.replaceState({},'',location.pathname);renderList();notify('คืนชุดข้อมูลสังเคราะห์แล้ว');};return;}});
document.addEventListener('change',event=>{const selector=event.target.closest('[data-preview-fixture]');if(selector&&selector.value)discardDraftThen(()=>{modal.close();renderDetail(selector.value);});});
window.addEventListener('beforeunload',()=>clearPreviewExport());
